-- One-time import of the albums migrated from the old Hugo gallery.
-- Their files are already in the w4trc-photos bucket.
-- Run once: npx wrangler d1 execute w4trc-gallery --remote --file=seed/migrated-albums.sql

UPDATE albums SET cover_photo_id = (SELECT id FROM photos WHERE album_slug = 'field-day-2016' AND file = 'img-0941') WHERE slug = 'field-day-2016';

UPDATE albums SET cover_photo_id = (SELECT id FROM photos WHERE album_slug = 'field-day-2017' AND file = 'img-3882') WHERE slug = 'field-day-2017';

UPDATE albums SET cover_photo_id = (SELECT id FROM photos WHERE album_slug = 'field-day-2020' AND file = '4') WHERE slug = 'field-day-2020';

UPDATE albums SET cover_photo_id = (SELECT id FROM photos WHERE album_slug = 'field-day-2021' AND file = '4jpeg') WHERE slug = 'field-day-2021';

UPDATE albums SET cover_photo_id = (SELECT id FROM photos WHERE album_slug = 'field-day-2022' AND file = 'k2kar-20220626-112954') WHERE slug = 'field-day-2022';






